 stage.addEventListener('pointerdown',pointerDown,{signal});stage.addEventListener('pointermove',pointerMove,{signal});stage.addEventListener('pointerup',pointerUp,{signal});stage.addEventListener('pointercancel',pointerUp,{signal});stage.addEventListener('pointerleave',()=>{hover=null;requestDraw();},{signal});stage.addEventListener('wheel',wheel,{signal,passive:false});stage.addEventListener('contextmenu',e=>e.preventDefault(),{signal});stage.addEventListener('keydown',keyDown,{signal});
