function line(from,to){if(!from||!to)return;const dx=to.x-from.x,dy=to.y-from.y,n=Math.max(Math.abs(dx),Math.abs(dy));for(let i=0;i<=n;i++){const x=Math.round(from.x+dx*(n?i/n:0)),y=Math.round(from.y+dy*(n?i/n:0));paint({x,y,index:y*S.result.gw+x});}}
function fill(p){if(!p||!S.result||!S.result.colors[S.colorIndex])return;const from=S.result.grid[p.index],to=S.colorIndex;if(from===to)return;snapshot();const grid=S.result.grid,w=S.result.gw,h=S.result.gh,queue=[p.index];grid[p.index]=to;while(queue.length){const i=queue.pop(),x=i%w,y=Math.floor(i/w);for(const n of [x?i-1:-1,x<w-1?i+1:-1,y?i-w:-1,y<h-1?i+w:-1])if(n>=0&&grid[n]===from){grid[n]=to;queue.push(n);}}markEdited();}
function pointerDown(e){if(!S.result||e.button>1)return;e.preventDefault();const p=cellAt(e);$('#pattern-maker-stage').focus({preventScroll:true});$('#pattern-maker-stage').setPointerCapture(e.pointerId);if(S.tool==='pan'||e.button===1||e.altKey){pan={id:e.pointerId,x:e.clientX,y:e.clientY,ox:S.view.x,oy:S.view.y};S.view.fit=false;return;}if(S.tool==='pick'){if(p&&S.result.grid[p.index]!==EMPTY){S.colorIndex=S.result.grid[p.index];S.tool='brush';updateStatus();say(`已选择 ${S.result.colors[S.colorIndex].code}`);}return;}if(S.tool==='fill'){fill(p);return;}if(p){stroke={id:e.pointerId,before:copyResult(S.result),last:p,changed:false};paint(p);}}
function pointerMove(e){if(pan){S.view.x=pan.ox+e.clientX-pan.x;S.view.y=pan.oy+e.clientY-pan.y;requestDraw();return;}const p=cellAt(e);hover=p;const label=root?.querySelector('.pm-hover-position');if(label)label.textContent=p?`第 ${p.x+1} 列 · 第 ${p.y+1} 行${S.result.colors[S.result.grid[p.index]]?' · '+S.result.colors[S.result.grid[p.index]].code:''}`:'';if(stroke&&p){line(stroke.last,p);stroke.last=p;}requestDraw();}
function pointerUp(e){pan=null;if(stroke){if(stroke.changed){S.undo.push(stroke.before);if(S.undo.length>35)S.undo.shift();S.redo=[];markEdited();}stroke=null;}try{$('#pattern-maker-stage')?.releasePointerCapture(e.pointerId);}catch{};}
function zoom(factor,cx,cy){if(!S.result)return;const stage=$('#pattern-maker-stage'),old=S.view.zoom,r=stage.getBoundingClientRect(),mx=cx==null?r.width/2:cx-r.left,my=cy==null?r.height/2:cy-r.top,z=clamp(old*factor,.2,80);S.view.x=mx-(mx-S.view.x)/old*z;S.view.y=my-(my-S.view.y)/old*z;S.view.zoom=z;S.view.fit=false;requestDraw();}
