function keyDown(e){if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'){e.preventDefault();historyStep(e.shiftKey);return;}if(e.key==='0'){e.preventDefault();S.view.fit=true;requestDraw();}if(e.key==='+'||e.key==='='){e.preventDefault();zoom(1.15);}if(e.key==='-'){e.preventDefault();zoom(1/1.15);}if(e.key.startsWith('Arrow')){e.preventDefault();S.view.fit=false;S.view.x+=e.key==='ArrowLeft'?24:e.key==='ArrowRight'?-24:0;S.view.y+=e.key==='ArrowUp'?24:e.key==='ArrowDown'?-24:0;requestDraw();}}
function historyStep(redo){const stack=redo?S.redo:S.undo,other=redo?S.undo:S.redo;if(!stack.length)return;other.push(copyResult(S.result));S.result=stack.pop();S.colorIndex=clamp(S.colorIndex,0,S.result.colors.length-1);markEdited();}
async function readImage(url){return new Promise((resolve,reject)=>{const image=new Image();image.onload=()=>{const scale=Math.min(1,1600/Math.max(image.naturalWidth,image.naturalHeight)),c=canvas(Math.max(1,Math.round(image.naturalWidth*scale)),Math.max(1,Math.round(image.naturalHeight*scale)));c.getContext('2d').drawImage(image,0,0,c.width,c.height);resolve(c);};image.onerror=()=>reject(new Error('这张图片暂时无法读取，请尝试 PNG 或 JPG。'));image.src=url;});}
async function loadFile(file){if(!file)return;if(!file.type.startsWith('image/')){say('请选择图片文件。');return;}const job=++S.sourceJob,url=URL.createObjectURL(file);try{const c=await readImage(url);if(job!==S.sourceJob)return;setSource(c,file.name.replace(/\.[^.]+$/,'')||'我的图纸');}catch(e){say(e.message);}finally{URL.revokeObjectURL(url);}}
